-- Publicaciones editoriales de los diez niveles. Ejecutar el verificador de SVG antes de este archivo.
BEGIN;

DO $$
DECLARE problema TEXT;
BEGIN
  IF to_regclass('escenario') IS NULL OR to_regclass('intento') IS NULL
     OR to_regclass('criterio_uv_ut') IS NULL OR to_regclass('intento_uv_ut') IS NULL
     OR to_regclass('intento_catalogo_v1') IS NULL OR to_regclass('resultado_uv_ut') IS NULL THEN
    RAISE EXCEPTION '018 requiere el esquema completo de 017';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='intento'::regclass
    AND tgname='congelar_catalogo_intento_v1' AND NOT tgisinternal) THEN
    RAISE EXCEPTION '018 requiere el disparador de snapshots V1 de 017';
  END IF;
  IF to_regrole('metronet_app') IS NULL THEN
    RAISE EXCEPTION '018 requiere el rol metronet_app';
  END IF;
  IF (SELECT COUNT(*) FROM escenario WHERE progresivo=TRUE AND modo='NIVEL') <> 10
     OR EXISTS (SELECT 1 FROM generate_series(1,10) AS g(numero_nivel) WHERE
       (SELECT COUNT(*) FROM escenario e WHERE e.progresivo=TRUE AND e.modo='NIVEL' AND e.numero=g.numero_nivel) <> 1) THEN
    RAISE EXCEPTION '018 requiere exactamente los diez niveles progresivos únicos';
  END IF;
  IF EXISTS (SELECT 1 FROM escenario e LEFT JOIN criterio_uv_ut c ON c.id_escenario=e.id_escenario
    WHERE e.progresivo=TRUE AND e.modo='NIVEL' AND e.numero BETWEEN 4 AND 10
      AND (c.id_escenario IS NULL OR c.version < 1 OR c.limite_ut < 1 OR c.presupuesto_uv <= 0)) THEN
    RAISE EXCEPTION '018 requiere criterio UV/UT válido en los niveles 4 a 10';
  END IF;
  IF EXISTS (SELECT 1 FROM intento i JOIN escenario e ON e.id_escenario=i.id_escenario
    WHERE e.progresivo=TRUE AND e.modo='NIVEL'
      AND NOT EXISTS (SELECT 1 FROM intento_catalogo_v1 v WHERE v.id_intento=i.id_intento)
      AND NOT EXISTS (SELECT 1 FROM intento_uv_ut v WHERE v.id_intento=i.id_intento)) THEN
    RAISE EXCEPTION '018 encontró un intento progresivo sin snapshot V1/V2';
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS nivel_publicacion (
  id_nivel_publicacion BIGSERIAL PRIMARY KEY,
  id_escenario INTEGER NOT NULL REFERENCES escenario(id_escenario),
  numero_version INTEGER NOT NULL CHECK (numero_version > 0),
  version_criterio_uv_ut INTEGER CHECK (version_criterio_uv_ut > 0),
  contenido JSONB NOT NULL,
  red_referencia JSONB NOT NULL DEFAULT '{}'::jsonb,
  huella TEXT NOT NULL,
  autor_id INTEGER REFERENCES usuario(id_usuario) ON DELETE SET NULL,
  publicado_en TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
  corte_id_intento INTEGER,
  confirmacion_editorial BOOLEAN NOT NULL DEFAULT FALSE,
  CONSTRAINT uk_nivel_publicacion_version UNIQUE(id_escenario,numero_version)
);
CREATE INDEX IF NOT EXISTS idx_nivel_publicacion_escenario_actual
  ON nivel_publicacion(id_escenario, numero_version DESC);

CREATE TABLE IF NOT EXISTS nivel_publicacion_tarjeta (
  id_nivel_publicacion BIGINT NOT NULL REFERENCES nivel_publicacion(id_nivel_publicacion),
  posicion SMALLINT NOT NULL CHECK (posicion BETWEEN 1 AND 6),
  id_tarjeta TEXT NOT NULL,
  titulo TEXT NOT NULL,
  texto TEXT NOT NULL,
  aprendizaje TEXT NOT NULL,
  fuente TEXT NOT NULL,
  url_fuente TEXT NOT NULL,
  descripcion_imagen TEXT NOT NULL,
  id_svg_catalogo TEXT NOT NULL,
  sha256_svg CHAR(64) NOT NULL,
  PRIMARY KEY(id_nivel_publicacion,posicion),
  CONSTRAINT uk_nivel_publicacion_tarjeta_id UNIQUE(id_nivel_publicacion,id_tarjeta)
);

CREATE TABLE IF NOT EXISTS nivel_borrador (
  id_escenario INTEGER PRIMARY KEY REFERENCES escenario(id_escenario),
  version_base INTEGER NOT NULL CHECK (version_base > 0),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision > 0),
  contenido JSONB NOT NULL,
  red_referencia JSONB NOT NULL DEFAULT '{}'::jsonb,
  tarjetas JSONB NOT NULL,
  autor_id INTEGER REFERENCES usuario(id_usuario) ON DELETE SET NULL,
  actualizado_en TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);

ALTER TABLE intento ADD COLUMN IF NOT EXISTS id_nivel_publicacion BIGINT
  REFERENCES nivel_publicacion(id_nivel_publicacion);
CREATE INDEX IF NOT EXISTS idx_intento_nivel_publicacion
  ON intento(id_nivel_publicacion) WHERE id_nivel_publicacion IS NOT NULL;

-- Esta versión inicial congela exclusivamente el estado conocido al instalar 018.
INSERT INTO nivel_publicacion(id_escenario,numero_version,version_criterio_uv_ut,contenido,
  red_referencia,huella,corte_id_intento)
SELECT e.id_escenario,1,c.version,
  jsonb_build_object('desafio',jsonb_build_object('nombre',e.nombre,'relato',
    COALESCE(relatos.relato,e.objetivo),'objetivo',e.objetivo,'instrucciones',e.instrucciones,
    'dificultad',e.dificultad),'reglasExito',e.reglas_exito,
    'herramientasHabilitadas',e.herramientas_habilitadas,'criterioUvUt',
    CASE WHEN c.id_escenario IS NULL THEN NULL ELSE jsonb_build_object('limiteUt',c.limite_ut,'presupuestoUv',c.presupuesto_uv) END,
    'ayudas','[]'::jsonb),
  '{}'::jsonb, md5(e.id_escenario::text || e.reglas_exito::text || e.herramientas_habilitadas::text),
  (SELECT MAX(id_intento) FROM intento)
FROM escenario e LEFT JOIN criterio_uv_ut c ON c.id_escenario=e.id_escenario
LEFT JOIN (VALUES
  (1,'Ari despliega el mapa sobre la mesa. Sol señala dos lugares que necesitan conectarse y Dani propone comenzar por un recorrido sencillo. El proyecto de metro hipotético empieza con una primera línea.'),
  (2,'La primera línea ya une dos lugares, pero Sol observa que deja fuera otro destino. Ari extiende el trazado y Dani revisa que el recorrido tenga continuidad. El equipo descubre que crecer exige conectar, no solo dibujar estaciones.'),
  (3,'Sobre el plano, todo parece listo. Dani les recuerda que una unidad de metro necesita una ruta sin cortes para circular. Ari y Sol revisan la red antes de poner en marcha el primer tren de su propuesta.'),
  (4,'El equipo mira dos extremos de Montevideo: Palacio Legislativo y Rambla de Carrasco. Sol plantea unirlos sin perder de vista los barrios; Dani pide probar en la simulación si la propuesta realmente funciona.'),
  (5,'El mapa suma Terminal Tres Cruces y Plaza Virgilio. Ari busca un trazado que acerque esos destinos; Sol comprueba los barrios y Dani compara el recorrido en otra ejecución. Cada decisión cambia la lectura de la red.'),
  (6,'El Mirador de la Intendencia entra en la discusión. Para atender el Centro junto al Oeste y el Este, Sol revisa la cobertura, Ari ajusta las conexiones y Dani propone comparar resultados antes de dar el diseño por resuelto.'),
  (7,'El avance hacia Brazo Oriental complica la red. Ari plantea dos líneas y Sol encuentra un punto donde cambiar entre ellas. Dani quiere comprobar que ambas puedan operar: el primer transbordo se convierte en una decisión del equipo.'),
  (8,'La red llega al entorno del Estadio Centenario. Sol detecta nuevos destinos; Ari organiza más líneas y transbordos. Dani compara cómo responde cada unidad y después el conjunto, porque una red mayor pide coordinación.'),
  (9,'El equipo tiene poco margen para sumar estaciones. Sol exige acercarlas a los lugares clave, Ari simplifica el trazado y Dani prueba distintos supuestos. Descubren que una red más precisa puede ser más útil que una más extensa.'),
  (10,'Llega la presentación final del proyecto. Ari defiende las conexiones, Sol explica la cobertura de barrios y zonas, y Dani muestra las comparaciones de operación. El equipo reúne lo aprendido en una red hipotética completa y revisable.')
) AS relatos(numero,relato) ON relatos.numero=e.numero
WHERE e.progresivo=TRUE AND e.modo='NIVEL'
ON CONFLICT(id_escenario,numero_version) DO NOTHING;

INSERT INTO nivel_publicacion_tarjeta(id_nivel_publicacion,posicion,id_tarjeta,titulo,texto,
  aprendizaje,fuente,url_fuente,descripcion_imagen,id_svg_catalogo,sha256_svg)
SELECT p.id_nivel_publicacion,t.posicion,t.id,t.titulo,t.texto,t.aprendizaje,t.fuente,t.url,
  t.descripcion,t.imagen,t.sha256
FROM jsonb_to_recordset($metronet_tarjetas$
[{"numero":1,"posicion":1,"id":"1-1","titulo":"El comienzo fue entre dos estaciones","texto":"El 1 de enero de 1869 se inauguró el primer tramo ferroviario de Uruguay, entre Bella Vista y Las Piedras. Era un ferrocarril, no un metro. Aquella conexión permite pensar una pregunta que sigue vigente: ¿qué lugares conviene unir primero para que una red resulte útil?","aprendizaje":"Elegir conexiones útiles antes de ampliar la red.","fuente":"AFE, historia ferroviaria","url":"https://www.afe.com.uy/historia.php","descripcion":"Dos estaciones y una locomotora esquemática sobre una vía, con la fecha 1869.","imagen":"/assets/educacion/ferrocarril-1869.svg","sha256":"5da528376192bf29a853fc9c2c4f7276beffdc0b7d950c8ff5fee4c497aa8ecf"},{"numero":1,"posicion":2,"id":"1-2","titulo":"El tren también construyó barrios","texto":"El desarrollo ferroviario dejó huellas fuera de las vías. En Peñarol, la instalación de talleres y estación en torno a 1890–1891 estuvo acompañada por viviendas para trabajadores y personal jerárquico. Una red de transporte puede relacionar hogares, empleos y servicios, y transformar la organización de un barrio.","aprendizaje":"Una estación forma parte de un entorno urbano.","fuente":"Intendencia de Montevideo, patrimonio de Peñarol","url":"https://montevideo.gub.uy/tipo/area-tematica/emprendimientos-empleo-y-economia/centro-economico-territorial-penarol-0","descripcion":"Taller, estación y viviendas unidos por senderos en un esquema urbano.","imagen":"/assets/educacion/penarol-barrio.svg","sha256":"672bde2f8fd6f8cef85fa659306190fdfc88641f38e848653b6b000e24cdbac3"},{"numero":1,"posicion":3,"id":"1-3","titulo":"Un tren con relato en vivo","texto":"En 1937, el Ferrocarril Central del Uruguay estrenó excursiones «fonoeléctricas». Dos locutores relataban el viaje desde un coche transmisor, y los pasajeros los escuchaban por parlantes distribuidos en los salones. La experiencia recuerda que el ferrocarril también fue una forma de pasear, conocer lugares y compartir información durante el recorrido.","aprendizaje":"Reconocer usos recreativos y culturales del ferrocarril uruguayo.","fuente":"AFE, Historia Ferroviaria del Uruguay, 1937","url":"https://www.afe.com.uy/historia.php","descripcion":"Dos locutores transmiten el relato del viaje a los parlantes de los vagones de una excursión ferroviaria de 1937.","imagen":"/assets/educacion/excursion-fonoelectrica-1937.svg","sha256":"b01e3e9e463a6419787a9338bfa849baafa74e34282df698e82b82d600545c6a"},{"numero":1,"posicion":4,"id":"1-4","titulo":"Las señales también tienen historia","texto":"En 1931, el Ferrocarril Central del Uruguay instaló señalización eléctrica con luces de tres posiciones en el tramo de vía doble entre Central, Empalme Tablada y Peñarol. Las señales servían para gobernar la marcha de los trenes. La historia ferroviaria también incluye tecnologías de coordinación que los pasajeros no siempre ven.","aprendizaje":"Identificar la señalización como parte de la infraestructura ferroviaria.","fuente":"AFE, Historia Ferroviaria del Uruguay, 1931","url":"https://www.afe.com.uy/historia.php","descripcion":"Esquema de dos vías y una señal ferroviaria junto a Central, Empalme Tablada y Peñarol, con fecha 1931.","imagen":"/assets/educacion/senales-1931.svg","sha256":"d7e21286535498d1b75213ee258dead45863d1a1bd0b7c2995015b480df51bd4"},{"numero":1,"posicion":5,"id":"logistica-01-e","titulo":"Del mapa al grafo","texto":"En un ejercicio de ingeniería de software del MIT, el metro de Boston sirve para aprender grafos: estaciones y conexiones se convierten en una red que una computadora puede recorrer. Quien estudia Logística puede aplicar esa mirada a un plano ferroviario para reconocer sectores aislados y rutas posibles.","aprendizaje":"Representar estaciones como nodos y conexiones como enlaces","fuente":"MIT OpenCourseWare, 6.170 Laboratory in Software Engineering, Problem Set 4 (2005), problema 4, pp. 9–11 del PDF","url":"https://ocw.mit.edu/courses/6-170-laboratory-in-software-engineering-fall-2005/622329e7756955af70101639ecadeaab_ps4.pdf","descripcion":"Un plano de metro se simplifica en nodos y enlaces, conservando una estación aislada.","imagen":"/assets/educacion/logistica-01-e.svg","sha256":"65e31d027e32f5f393d64b52b7454bded1bda1d7f01be81e025985566e14cdf3"},{"numero":1,"posicion":6,"id":"logistica-01-f","titulo":"Un origen necesita un destino","texto":"La MTA publica estimaciones de viajes entre estaciones de origen y destino, organizadas por horario. Saber cuántas personas entran en una estación no revela adónde van. Como ejercicio de Logística, dibujá tres viajes hipotéticos sobre tu red: ¿las líneas unen ambos extremos o dejan conexiones sin resolver?","aprendizaje":"Analizar pares de estaciones, además de contar entradas","fuente":"MTA / Estado de Nueva York, Subway Origin-Destination Ridership Estimate: 2024, descripción del conjunto de datos","url":"https://data.ny.gov/Transportation/MTA-Subway-Origin-Destination-Ridership-Estimate-2/jsu2-fbtj","descripcion":"Tres viajes hipotéticos muestran qué orígenes y destinos logra conectar una red de metro.","imagen":"/assets/educacion/logistica-01-f.svg","sha256":"0d4cb28feea8ebb3709cde80052bada0ac78fcef7d0eae339ed4fe313e0b173d"},{"numero":2,"posicion":1,"id":"2-1","titulo":"Londres abrió camino en 1863","texto":"El 10 de enero de 1863 abrió en Londres el primer ferrocarril subterráneo del mundo, entre Paddington y Farringdon Street. La red actual nació de aquella primera conexión. Su historia recuerda que una gran red puede crecer por etapas, a partir de un recorrido inicial bien elegido.","aprendizaje":"Una red puede desarrollarse gradualmente.","fuente":"Transport for London, historia del Underground","url":"https://foi.tfl.gov.uk/FOI-0773-2324/TUBE160%20Heritage%20Leaflet.pdf","descripcion":"Una línea inicial de 1863 que se ramifica en un diagrama ficticio.","imagen":"/assets/educacion/londres-1863.svg","sha256":"2722f5b1af0f9550cfa7bf9c118011bfc8d3a659c09355fb4095bc5c7dcfa656"},{"numero":2,"posicion":2,"id":"2-2","titulo":"El pionero latinoamericano está cerca","texto":"Buenos Aires inauguró su Línea A el 1 de diciembre de 1913. El primer recorrido unía Plaza de Mayo con Plaza Miserere y fue el primer subterráneo de Latinoamérica. Durante 1914 la línea se extendió hacia otros barrios: ampliar una conexión existente también puede aumentar su utilidad.","aprendizaje":"Las extensiones incorporan nuevos destinos.","fuente":"Gobierno de Buenos Aires, historia de la Línea A","url":"https://buenosaires.gob.ar/gcaba_historico/jefaturadegabinete/movilidad/subte/nuestra-historia/nuestra-historia/linea-a","descripcion":"Dos extremos de una línea de 1913 y una extensión marcada para 1914.","imagen":"/assets/educacion/buenos-aires-1913.svg","sha256":"fc981dc5901dd0231ff3e4f3c7caf1678c11b43301b78b8ffd39efa5cf5aa664"},{"numero":2,"posicion":3,"id":"2-3","titulo":"Un pionero bajo una avenida","texto":"Budapest inauguró su ferrocarril subterráneo del Milenio el 2 de mayo de 1896. Fue el primero de Europa continental y se diseñó desde el inicio para funcionar con electricidad. Su recorrido bajo la avenida Andrássy muestra cómo una obra de transporte puede quedar ligada a la historia y al patrimonio de una ciudad.","aprendizaje":"Relacionar las redes históricas con su entorno urbano.","fuente":"BKV, historia del ferrocarril del Milenio","url":"https://www.bkv.hu/en/content/living-history-underground-budapests-millenium-underground-turns-130-05052026","descripcion":"Tren eléctrico en un túnel bajo una avenida de Budapest, en un esquema fechado en 1896.","imagen":"/assets/educacion/budapest-1896.svg","sha256":"8ce9f0fef3edc89f22a05047b9ba0524af85973e988b99127718f24d785f87c7"},{"numero":2,"posicion":4,"id":"2-4","titulo":"Tokio empezó con Asakusa y Ueno","texto":"El 30 de diciembre de 1927 abrió el primer tramo de subterráneo de Tokio, entre Asakusa y Ueno. Fue el primer metro de Asia, según su operador. El proyecto había comenzado a construirse en 1925: antes del primer viaje hubo una etapa de obras, distinta del funcionamiento cotidiano de la red.","aprendizaje":"Diferenciar construcción e inauguración de una línea.","fuente":"Tokyo Metro, History","url":"https://www.tokyometro.jp/lang_en/corporate/profile/history/index.html","descripcion":"Cronología de la construcción en 1925 y la inauguración en 1927 del tramo de Tokio entre Asakusa y Ueno.","imagen":"/assets/educacion/tokio-1927.svg","sha256":"abc8ed71797f8de5f8db555fadd580de7c1190aabd35e605b73950e94f6a6c61"},{"numero":2,"posicion":5,"id":"logistica-02-e","titulo":"Cruzar no es combinar","texto":"Los modelos de transporte representan los transbordos mediante enlaces específicos entre servicios. Dos líneas que se cruzan en un dibujo no garantizan intercambio. Para estudiantes de Logística, revisar una red de metro implica señalar dónde sería posible cambiar de línea y distinguir esos puntos de los simples cruces del trazado.","aprendizaje":"Distinguir un cruce geométrico de una conexión de transporte","fuente":"Department for Transport, TAG M3.2 Public Transport Assignment Modelling (2024), §§6.2.8–6.2.11","url":"https://assets.publishing.service.gov.uk/media/666af32effd07973a043d110/tag-unit-m3.2-public-transport-assignment-modelling.pdf","descripcion":"Un cruce sin estación se compara con una estación que permite cambiar entre dos líneas.","imagen":"/assets/educacion/logistica-02-e.svg","sha256":"a9f9cb56e7063c9ec45743e19d09fbcf17fa242963a4706800852862dfa3072e"},{"numero":2,"posicion":6,"id":"logistica-02-f","titulo":"Combinar también lleva tiempo","texto":"Una combinación puede incluir caminatas, cambios de nivel y espera del siguiente tren. La planificación de redes estudia esos componentes por separado. En un ejercicio de Logística, compará dos itinerarios de metro con igual cantidad de estaciones: el que exige más transbordos no necesariamente ofrece la misma experiencia de viaje.","aprendizaje":"Descomponer el transbordo en sus partes","fuente":"MIT OpenCourseWare, Public Transportation Systems, Lecture 15: Networks and Route Structure (2017), pp. 2 y 6 del PDF","url":"https://ocw.mit.edu/courses/1-258j-public-transportation-systems-spring-2017/3a9389405af95c3e4a02985c5262c358_MIT1_258JS17_lec15.pdf","descripcion":"Caminar, cambiar de nivel y esperar son partes de un transbordo entre trenes de metro.","imagen":"/assets/educacion/logistica-02-f.svg","sha256":"139f2e914638a84ff13a9bb6ecada3fdaeaaab3c8422b18d9352db295e3605be"},{"numero":3,"posicion":1,"id":"3-1","titulo":"Un tren cada cien segundos","texto":"En 2017, la línea Victoria de Londres aumentó su servicio de hora pico a 36 trenes por hora. Eso equivale a un intervalo medio de 100 segundos. La curiosidad muestra una idea importante: la capacidad de una línea depende tanto de cada tren como de la frecuencia del servicio.","aprendizaje":"Distinguir capacidad por vehículo y por hora.","fuente":"TfL, informe del programa de inversiones 2017–2018","url":"https://content.tfl.gov.uk/tfl-investment-programme-report-q3-2017-18.pdf","descripcion":"Reloj de cien segundos y tres trenes igualmente espaciados.","imagen":"/assets/educacion/frecuencia-100.svg","sha256":"99e47e8e5f0032d391da47b63de435d2bd49631c9c5b5e497c2e9111cf038283"},{"numero":3,"posicion":2,"id":"3-2","titulo":"Más frecuencia requiere coordinación","texto":"Para aumentar la frecuencia de la línea Victoria, Londres modificó señalización, trenes, alimentación eléctrica y vías. No bastaba con sumar vehículos. En una red real, transportar más personas requiere coordinar varios elementos para que los trenes puedan circular y detenerse con seguridad y con un servicio confiable.","aprendizaje":"Identificar límites de infraestructura antes de añadir capacidad.","fuente":"TfL, revisión del proyecto World Class Capacity","url":"https://content.tfl.gov.uk/pic-20170628-item07-lu-world-class-capacity.pdf","descripcion":"Cuatro piezas conectadas: tren, señal, energía y vía.","imagen":"/assets/educacion/capacidad-coordinada.svg","sha256":"2936b03b032fcd9a64af7ebb95037ef7ed93176f91099a486cc3be89f7506f1d"},{"numero":3,"posicion":3,"id":"3-3","titulo":"Una parada larga afecta a otros trenes","texto":"El tiempo que un tren permanece detenido en una estación influye en la capacidad de la línea. Un informe de la MTA explica que los trenes siguientes deben mantener una distancia segura; si las detenciones se alargan, pueden aumentar los intervalos. Por eso, el tiempo de ascenso y descenso también cuenta.","aprendizaje":"Reconocer el tiempo de parada como límite de capacidad.","fuente":"MTA, Subway Speed and Capacity Review","url":"https://www.mta.info/document/13046","descripcion":"Un tren se detiene en una estación mientras el siguiente espera a distancia, con un reloj que representa el intervalo.","imagen":"/assets/educacion/parada-y-frecuencia.svg","sha256":"f143cf939fdac68dbeb84f233f80bfad672e05aba694094bc8a22d10f1062f4d"},{"numero":3,"posicion":4,"id":"3-4","titulo":"Un pasillo entre vagones","texto":"Los R211 de pasillo continuo presentados en Nueva York en 2023 incorporan paredes flexibles, parecidas a un acordeón, que conectan sus vagones. Esa unión permite circular por el interior entre coches. El ejemplo muestra que organizar un tren también consiste en pensar cómo se distribuyen y se mueven sus pasajeros.","aprendizaje":"Relacionar distribución interior y circulación de pasajeros.","fuente":"Kawasaki, presentación de los R211","url":"https://global.kawasaki.com/en/corp/newsroom/news/detail/?f=20230306_7827","descripcion":"Dos vagones de metro unidos por un fuelle cerrado y un pasillo interior continuo para los pasajeros.","imagen":"/assets/educacion/pasillo-continuo-r211.svg","sha256":"14007c31ac92b23bb52ade6903ce1148d007b1012549c1bbc68e0581a86b6760"},{"numero":3,"posicion":5,"id":"logistica-03-e","titulo":"Un atajo alrededor del centro","texto":"La Circle Line de Singapur enlaza otras líneas y permite evitar estaciones centrales muy concurridas, como City Hall y Raffles Place. Para estudiar Logística, probá en un plano de metro una conexión transversal entre barrios: puede crear itinerarios que antes obligaban a pasar por el centro de la red.","aprendizaje":"Evaluar conexiones transversales, además de recorridos hacia el centro","fuente":"Land Transport Authority, Circle Line, apartados Going Places Faster y Design and Architecture","url":"https://www.lta.gov.sg/content/ltagov/en/getting_around/public_transport/rail_network/circle_line.html","descripcion":"Una conexión transversal une dos barrios sin obligar a viajar por la estación central.","imagen":"/assets/educacion/logistica-03-e.svg","sha256":"90364d0062ff71627e8fed266147b743077c1ba5173f2d37b22c3ca548d1d327"},{"numero":3,"posicion":6,"id":"logistica-03-f","titulo":"El recorrido directo tiene valor","texto":"Entre los principios de diseño de redes del MIT aparece evitar recorridos innecesariamente sinuosos y facilitar conexiones. En una simulación de metro, estudiantes de Logística pueden comparar una línea que serpentea para alcanzar muchos lugares con dos líneas conectadas. El desafío es explicar qué cobertura se gana y qué rodeos aparecen.","aprendizaje":"Comparar cobertura territorial y rodeos del trazado","fuente":"MIT OpenCourseWare, Public Transportation Systems, Lecture 15: Networks and Route Structure (2017), pp. 2 y 6 del PDF","url":"https://ocw.mit.edu/courses/1-258j-public-transportation-systems-spring-2017/3a9389405af95c3e4a02985c5262c358_MIT1_258JS17_lec15.pdf","descripcion":"Dos diseños de metro conectan los mismos lugares mediante una línea sinuosa o dos líneas con intercambio.","imagen":"/assets/educacion/logistica-03-f.svg","sha256":"80151ad2c5a4d6a55a9fc4bb01737e8e734f119bbdebccb92b787b2bc248f52f"},{"numero":4,"posicion":1,"id":"4-1","titulo":"Montevideo ya viajaba con electricidad","texto":"Los tranvías eléctricos comenzaron a funcionar en Montevideo en 1906. Forman parte de la historia del transporte urbano uruguayo, aunque no eran una red de metro. Recordarlos ayuda a distinguir dos ideas: usar electricidad describe la energía del vehículo; ser tranvía o metro describe también cómo circula.","aprendizaje":"Electrificación y tipo de sistema son conceptos diferentes.","fuente":"Municipio E, historia del transporte de la Unión","url":"https://municipioe.montevideo.gub.uy/sites/municipioe/files/junio_09_zona_6.pdf","descripcion":"Tranvía esquemático con cable aéreo sobre una calle, rotulado 1906.","imagen":"/assets/educacion/tranvia-1906.svg","sha256":"9f632c86032f890c5e461d199b37a6b9bacc46883066196c195c54e6f9b5287b"},{"numero":4,"posicion":2,"id":"4-2","titulo":"Un metro puede ver el cielo","texto":"Un metro no tiene que circular siempre bajo tierra. Puede tener tramos subterráneos, elevados o en superficie. Una característica decisiva es que opera en infraestructura independiente del tránsito de calles y de peatones. Un tranvía, en cambio, puede compartir parte de su recorrido con la circulación urbana.","aprendizaje":"La separación del tránsito importa más que estar bajo tierra.","fuente":"UITP–UNIFE, definición de transporte ferroviario urbano","url":"https://www.uitp.org/wp-content/uploads/sites/7/2026/05/202309_URP_definition-of-urban-rail.pdf","descripcion":"Un tren esquemático en túnel, viaducto y superficie protegida.","imagen":"/assets/educacion/tres-trazados.svg","sha256":"65be5a9ea7ae6dddcb096fd00afe480a7d188223438003d96a53fea90037cf2b"},{"numero":4,"posicion":3,"id":"4-3","titulo":"Hay metros con neumáticos","texto":"En el metro de Ciudad de México hay trenes con ruedas metálicas y otros de rodadura neumática, que utilizan neumáticos. Así, dos vehículos llamados «metro» pueden tener soluciones técnicas diferentes. Comparar redes requiere mirar más que su nombre: también cuentan las vías, los equipos y la infraestructura compatible.","aprendizaje":"Distinguir el tipo de servicio de la tecnología de rodadura.","fuente":"STC Ciudad de México, Conformación de un tren","url":"https://www.metro.cdmx.gob.mx/operacion/conformacion-de-un-tren","descripcion":"Comparación esquemática de una rueda de acero sobre un riel y un neumático sobre una pista de rodadura de metro.","imagen":"/assets/educacion/rodadura-metro.svg","sha256":"0199e69384ea6df017acef2b8fb3221911399c3b6a6de55fd142344362b4f2b5"},{"numero":4,"posicion":4,"id":"4-4","titulo":"Un vehículo entre dos redes","texto":"En 2018 comenzó a funcionar un servicio de tranvía-tren entre Sheffield y Rotherham, en Inglaterra. Sus vehículos pueden circular tanto por la red de tranvías como por la ferroviaria. Para lograrlo fue necesario adaptar infraestructura y formas de operación: conectar redes exige compatibilidad, además de unir líneas en un mapa.","aprendizaje":"Comprender que la conexión física necesita compatibilidad técnica.","fuente":"Network Rail, inauguración del tranvía-tren","url":"https://www.networkrailmediacentre.co.uk/news/uks-first-tram-train-debuts-in-south-yorkshire","descripcion":"Un tranvía-tren continúa su recorrido desde una vía tranviaria urbana hacia un corredor ferroviario.","imagen":"/assets/educacion/tranvia-tren-2018.svg","sha256":"e228058d15d5d79894ce3e824a3bcf4cea0e43a6fac6be6c21b5c105756ff53a"},{"numero":4,"posicion":5,"id":"logistica-04-e","titulo":"La distancia entre estaciones importa","texto":"Ubicar estaciones más cerca puede acortar el acceso a pie, pero suma detenciones al recorrido. Los modelos de planificación estudian ese equilibrio entre acceso, tiempo a bordo y operación. Para estudiantes de Logística, mover estaciones en un plano de metro permite discutir qué barrios se acercan al servicio y qué decisiones requieren más datos.","aprendizaje":"Equilibrar separación de estaciones y acceso al servicio","fuente":"MIT OpenCourseWare, Public Transportation Systems, Lecture 11: Macro Design Models for a Single Route (2017), p. 3 del PDF","url":"https://ocw.mit.edu/courses/1-258j-public-transportation-systems-spring-2017/0f318ed94f7099b98e3ee29630ec11f9_MIT1_258JS17_lec11.pdf","descripcion":"Una misma línea con estaciones separadas o cercanas muestra el equilibrio entre caminar y detenerse.","imagen":"/assets/educacion/logistica-04-e.svg","sha256":"da865b2f23ce34ccca2c41ac952d3d25e5ae259f0a6e4a75b47f1053680c90ad"},{"numero":4,"posicion":6,"id":"logistica-04-f","titulo":"Un destino se cuenta una vez","texto":"El modelo británico de conectividad evita volver a contabilizar un destino ya alcanzado. Esa idea sirve para analizar cobertura de metro: dos estaciones cercanas pueden atender el mismo hospital. Como ejercicio de Logística, compará destinos distintos cubiertos antes y después de mover una estación, sin confundir más paradas con más lugares atendidos.","aprendizaje":"Medir cobertura adicional sin duplicar destinos","fuente":"Department for Transport, Transport connectivity metric, apartados The model y Factors affecting node values","url":"https://www.gov.uk/government/publications/transport-connectivity-metric/transport-connectivity-metric","descripcion":"Dos estaciones atienden el mismo hospital; mover una permite incorporar una biblioteca sin contar dos veces el hospital.","imagen":"/assets/educacion/logistica-04-f.svg","sha256":"2086286e5bf141d256dc1e20c492d970eda394e760570368e440e8d208cf8638"},{"numero":5,"posicion":1,"id":"5-1","titulo":"Llegar al andén no siempre basta","texto":"Una estación puede ofrecer ascensores hasta el andén y todavía tener un escalón o una separación al entrar al tren. Por eso, Transport for London distingue entre acceso sin escalones hasta el andén y hasta el vehículo. Una conexión útil debe considerar el recorrido completo de las personas.","aprendizaje":"La accesibilidad debe mantenerse durante todo el viaje.","fuente":"TfL, acceso sin escalones","url":"https://tfl.gov.uk/travel-information/improvements-and-projects/step-free-access?intcmp=1954","descripcion":"Recorrido de calle a ascensor, andén y tren, con una separación indicada.","imagen":"/assets/educacion/acceso-anden.svg","sha256":"da018c690fc66c3c1e3ea84a41cbe8430ec5be91ae3ebcfc672062b36124d19e"},{"numero":5,"posicion":2,"id":"5-2","titulo":"El viaje empieza antes de la estación","texto":"El IPCC destaca que el transporte público y la infraestructura para caminar o andar en bicicleta pueden favorecer viajes con menores emisiones. Las estaciones forman parte de ese conjunto. Ubicar una parada cerca de los destinos ayuda, pero también importa que existan recorridos cómodos y seguros para llegar hasta ella.","aprendizaje":"Considerar el acceso a la red además del trayecto en tren.","fuente":"IPCC, AR6, resumen para responsables de políticas","url":"https://www.ipcc.ch/report/ar6/wg3/chapter/summary-for-policymakers/","descripcion":"Estación vinculada con vereda, bicicletero, viviendas y servicios.","imagen":"/assets/educacion/acceso-estacion.svg","sha256":"5abe8fbe217d57bf23d4d68a16b615d05025994bcb48abd4d3baabcd459a1724"},{"numero":5,"posicion":3,"id":"5-3","titulo":"El piso también da información","texto":"En estaciones del metro de Londres, el pavimento con relieve ayuda a personas ciegas o con baja visión a detectar zonas importantes del andén. Sus patrones pueden percibirse con los pies o con un bastón. La accesibilidad también consiste en dar información que no dependa de leer un cartel.","aprendizaje":"Diseñar información que pueda percibirse de distintas maneras.","fuente":"TfL, Haringey station upgrades unveiled","url":"https://tfl.gov.uk/info-for/media/press-releases/2006/may/haringey-station-upgrades-unveiled","descripcion":"Una persona detecta con su bastón el pavimento táctil que advierte sobre la cercanía del borde del andén.","imagen":"/assets/educacion/pavimento-tactil.svg","sha256":"6c40658b221a7eac26a851aad0ca479942267f46bb2e789af4b1ae561a388d1a"},{"numero":5,"posicion":4,"id":"5-4","titulo":"Un aviso puede verse y oírse","texto":"Los trenes más nuevos del metro de Londres ofrecen avisos tanto audibles como visibles a bordo. Presentar la información de dos maneras ayuda a que más personas puedan seguir el viaje. Una red accesible necesita comunicar destinos y paradas con claridad, además de permitir el acceso físico al vehículo.","aprendizaje":"Combinar información visual y sonora para orientar el viaje.","fuente":"TfL, Plan an accessible journey","url":"https://tfl.gov.uk/transport-accessibility/plan-an-accessible-journey","descripcion":"Pantalla y altavoz de un vagón comunican la misma próxima parada de una red ficticia.","imagen":"/assets/educacion/avisos-audiovisuales.svg","sha256":"5efb186bcc0dad126c009bb4ac3ea75ee46da87ac4aefad484cdcbd1023dc92f"},{"numero":5,"posicion":5,"id":"logistica-05-e","titulo":"La flota también debe volver","texto":"Para sostener un servicio importa el ciclo completo del tren: ida, vuelta y tiempos en las terminales. En un ejemplo de aula, un ciclo de sesenta minutos con salidas cada diez requiere seis trenes en circulación. Estudiantes de Logística pueden calcular qué ocurre si alargan la línea, manteniendo las mismas salidas.","aprendizaje":"Relacionar duración del ciclo, intervalo y flota necesaria","fuente":"MIT OpenCourseWare, Public Transportation Systems, Lecture 12: Frequency Determination (2017), p. 2 del PDF","url":"https://ocw.mit.edu/courses/1-258j-public-transportation-systems-spring-2017/dcc9ef83281e06ee934b290488621f90_MIT1_258JS17_lec12.pdf","descripcion":"En un ejemplo ideal, seis trenes sostienen salidas cada diez minutos cuando cada ciclo dura una hora.","imagen":"/assets/educacion/logistica-05-e.svg","sha256":"241e50bb0d516e3573a5bb90a17d5435c80c57d244538ef0f5e5b5f8b430824f"},{"numero":5,"posicion":6,"id":"logistica-05-f","titulo":"El promedio puede engañar","texto":"En servicios frecuentes, la espera depende tanto del intervalo medio como de su regularidad. Dos metros pueden ofrecer igual cantidad de trenes por hora y dejar huecos muy distintos entre llegadas. En Logística, comparar secuencias de horarios hipotéticos ayuda a explicar por qué contar trenes no alcanza para evaluar la calidad del servicio.","aprendizaje":"Distinguir cantidad de trenes y regularidad de las llegadas","fuente":"MIT OpenCourseWare, Public Transportation Systems, Lecture 20: Transit Service Reliability (2017), p. 2 del PDF","url":"https://ocw.mit.edu/courses/1-258j-public-transportation-systems-spring-2017/3780d832f90b2d2cd2c9b772924a32c3_MIT1_258JS17_lec20.pdf","descripcion":"Dos secuencias con la misma cantidad de trenes muestran intervalos uniformes o un hueco largo entre llegadas.","imagen":"/assets/educacion/logistica-05-f.svg","sha256":"e8820be5c149c52e9f480ceabc2f517efe28fbb5fb773029139b79a00281a3be"},{"numero":6,"posicion":1,"id":"6-1","titulo":"La ocupación también cuenta","texto":"El IPCC señala que los ómnibus y trenes con alta ocupación pueden reducir considerablemente las emisiones por pasajero y kilómetro. El resultado cambia según cuántas personas viajan y qué energía se utiliza. Por eso, una red ambientalmente útil necesita servicios que respondan a viajes reales, no solamente vehículos nuevos.","aprendizaje":"Relacionar demanda atendida con emisiones por pasajero.","fuente":"IPCC, AR6, capítulo 10","url":"https://www.ipcc.ch/report/ar6/wg3/downloads/report/IPCC_AR6_WGIII_Chapter10.pdf","descripcion":"Dos trenes iguales con ocupación visual diferente y sin cifras de ahorro.","imagen":"/assets/educacion/ocupacion-tren.svg","sha256":"448d4a166e8f2221854b4e985ce88fa28801cbdfdcf8d911ccc821b152cc9baf"},{"numero":6,"posicion":2,"id":"6-2","titulo":"Importa de dónde viene la electricidad","texto":"Según el MIEM, el 99% de la generación eléctrica de Uruguay provino de fuentes renovables en 2024. Ese dato se refiere a electricidad, no a toda la energía utilizada en el país. Al evaluar transporte eléctrico, conocer cómo se genera su electricidad es parte de la comparación ambiental.","aprendizaje":"Diferenciar matriz eléctrica y consumo total de energía.","fuente":"MIEM, Balance Energético Preliminar 2024","url":"https://www.gub.uy/ministerio-industria-energia-mineria/comunicacion/noticias/uruguay-vuelve-registrar-niveles-record-fuentes-renovables-matriz-generacion","descripcion":"Enchufe conectado con agua, viento, biomasa y sol; fecha 2024.","imagen":"/assets/educacion/electricidad-2024.svg","sha256":"e4f046f86b2ed9ea03b2867112fb6bf70ae7c02d8f0401e7057f6cb9fde26e56"},{"numero":6,"posicion":3,"id":"6-3","titulo":"Un metro eléctrico también produce polvo","texto":"En el metro de Londres, el polvo incluye partículas metálicas producidas por el desgaste de ruedas, rieles y frenos. TfL mide sus niveles y realiza limpiezas específicas en las zonas más afectadas. Usar electricidad no elimina la necesidad de cuidar el aire dentro de estaciones y túneles.","aprendizaje":"Incluir medición y limpieza en el cuidado ambiental del metro.","fuente":"TfL, Improving air quality on the Tube","url":"https://tfl.gov.uk/corporate/about-tfl/improving-air-quality-on-the-tube","descripcion":"El desgaste de ruedas y rieles genera partículas en un túnel de metro; equipos las miden y retiran.","imagen":"/assets/educacion/polvo-subterraneo.svg","sha256":"5541ea198d72b31f1e8af631fc8f39067b4886e41cb8eaa923e950a6fcd85387"},{"numero":6,"posicion":4,"id":"6-4","titulo":"Las vías también hacen ruido","texto":"El contacto entre ruedas metálicas y rieles produce vibraciones que pueden llegar a edificios cercanos. En Londres, el mantenimiento incluye alisar irregularidades de los rieles y reemplazar piezas desgastadas para reducir ruido y vibración. La calidad ambiental de una red también depende de cómo se cuidan sus vías.","aprendizaje":"Incluir ruido y mantenimiento en la evaluación ambiental.","fuente":"TfL, Reducing noise & vibration","url":"https://tfl.gov.uk/corporate/about-tfl/reducing-noise-and-vibration","descripcion":"Comparación de una rueda sobre un riel irregular y uno alisado, con menor vibración en el segundo.","imagen":"/assets/educacion/ruido-riel.svg","sha256":"2e442c7745242b8a5692ac51b0dddf79b722730e3e7d93f1f4c1bf17e9401ae1"},{"numero":6,"posicion":5,"id":"logistica-06-e","titulo":"Mirar el tramo más cargado","texto":"La planificación de frecuencias considera las cargas máximas, que pueden cambiar según la hora. Un promedio de toda la línea puede esconder un tramo exigido. Para aprender Logística, asigná en papel viajes hipotéticos entre estaciones de metro y contá cuántos atraviesan cada segmento: localizar ese tramo ayuda a formular mejores preguntas.","aprendizaje":"Distinguir carga media y carga máxima por segmento","fuente":"MIT OpenCourseWare, Public Transportation Systems, Lecture 12: Frequency Determination (2017), p. 2 del PDF","url":"https://ocw.mit.edu/courses/1-258j-public-transportation-systems-spring-2017/dcc9ef83281e06ee934b290488621f90_MIT1_258JS17_lec12.pdf","descripcion":"Tres viajes ficticios coinciden en el tramo B–C, que concentra más recorridos que los extremos.","imagen":"/assets/educacion/logistica-06-e.svg","sha256":"bf5030d6228cf36e48c6c861c49e488494dccf4cb8de98158d06686d64587549"},{"numero":6,"posicion":6,"id":"logistica-06-f","titulo":"Una estación junto al estadio","texto":"La estación Stadium de Singapur fue diseñada para recibir aumentos de público durante eventos deportivos y espectáculos. Un destino no genera siempre la misma actividad. En una práctica de Logística, imaginá dos situaciones para tu red de metro: un día habitual y la salida de un evento. ¿Qué conexiones convendría revisar primero?","aprendizaje":"Examinar demanda concentrada por lugar y momento","fuente":"Land Transport Authority, Circle Line, apartados Going Places Faster y Design and Architecture","url":"https://www.lta.gov.sg/content/ltagov/en/getting_around/public_transport/rail_network/circle_line.html","descripcion":"Una estación próxima a un estadio recibe actividad distinta en un día habitual y al terminar un evento.","imagen":"/assets/educacion/logistica-06-f.svg","sha256":"c2086d91c1709cde755c352a73c1b2a710c45f3d116ce6aed0fbd2d473ecc03a"},{"numero":7,"posicion":1,"id":"7-1","titulo":"Un mapa no siempre mide distancias","texto":"El mapa de Harry Beck, publicado en Londres en 1933, usaba líneas horizontales, verticales y diagonales, con estaciones espaciadas de manera uniforme. No reproducía exactamente la geografía. Esa simplificación ayudaba a entender recorridos y conexiones: en un diagrama de red, cercanía visual y distancia real pueden ser diferentes.","aprendizaje":"Leer conexiones sin asumir que el dibujo está a escala.","fuente":"London Transport Museum, mapa de Harry Beck","url":"https://library.ltmuseum.co.uk/portal/Default/en-GB/RecordView/Index/106","descripcion":"La misma red ficticia como mapa geográfico y diagrama esquemático.","imagen":"/assets/educacion/mapa-beck.svg","sha256":"7bc85c123ba56ec2b79e671ad07cb83d99362c7d5a298498692ccd4e376e99b6"},{"numero":7,"posicion":2,"id":"7-2","titulo":"Una combinación abre más destinos","texto":"La Línea A de Buenos Aires conecta con otras líneas de subte y con el Ferrocarril Sarmiento en Plaza Miserere. Estas combinaciones permiten continuar viajes que una sola línea no cubre. Para pensar una red, no alcanza con contar estaciones: también importa qué recorridos quedan conectados entre sí.","aprendizaje":"Evaluar destinos alcanzables mediante combinaciones.","fuente":"Gobierno de Buenos Aires, conexiones de la Línea A","url":"https://buenosaires.gob.ar/gcaba_historico/jefaturadegabinete/movilidad/subte/nuestra-historia/nuestra-historia/linea-a","descripcion":"Dos líneas y un ferrocarril unidos por un nodo de intercambio.","imagen":"/assets/educacion/intercambio-lineas.svg","sha256":"590d963f6670cf7c6448e255a94579b18552db904236877de1f2e34985af273a"},{"numero":7,"posicion":3,"id":"7-3","titulo":"Una letra y un número orientan","texto":"Tokyo Metro identifica estaciones mediante una letra de línea y un número, además de sus nombres. Los códigos aparecen dentro de círculos del color de cada línea. Este sistema ayuda a contar las estaciones restantes y reconocer el sentido del viaje, incluso cuando el nombre de una parada resulta desconocido.","aprendizaje":"Combinar nombres, códigos y colores para orientarse.","fuente":"Tokyo Metro, explicación de números de estación","url":"https://www.tokyometro.jp/en/subwaymap/index.html","descripcion":"Línea ficticia con estaciones X01, X02 y X03, nombres y flecha de dirección.","imagen":"/assets/educacion/codigos-estaciones.svg","sha256":"03b25e927ee7183f0c9434e227c39ed3abe78da7ece03acf4508dfb2d8cec56d"},{"numero":7,"posicion":4,"id":"7-4","titulo":"Pasar no siempre significa parar","texto":"En Nueva York existen servicios locales y expresos. En los tramos preparados para ese funcionamiento, los locales se detienen en todas las estaciones y los expresos solo en las paradas expresas. Una vía que pasa por una estación no garantiza que todos sus trenes permitan subir o bajar allí.","aprendizaje":"Comparar patrones de parada y destinos atendidos.","fuente":"MTA, estudio Rockaway Beach Branch","url":"https://www.mta.info/document/10941","descripcion":"Un servicio local se detiene en cinco estaciones y uno expreso solo en tres, en una red de ejemplo.","imagen":"/assets/educacion/local-expreso.svg","sha256":"0c94314af9ddc1a1c309ce1c8545bb3e72f88ab19dc8a49ea9c340d3d483144b"},{"numero":7,"posicion":5,"id":"logistica-07-e","titulo":"No toda la flota está disponible","texto":"Los planes de flota ferroviaria contemplan vehículos fuera de servicio por mantenimiento y reservas para sostener la operación. La cantidad comprada no equivale a la cantidad disponible cada día. Como ejercicio de Logística, separá los trenes de un metro hipotético entre circulación, mantenimiento y reserva antes de proponer una frecuencia.","aprendizaje":"Distinguir flota total, disponible y asignada al servicio","fuente":"Federal Transit Administration, Circular C 5010.1F (1 de noviembre de 2024), pp. IV-39–IV-40","url":"https://www.transit.dot.gov/sites/fta.dot.gov/files/2024-10/C5010.1F-Circular-11-01-2024_0.pdf","descripcion":"La flota total de un metro se reparte entre trenes en servicio, mantenimiento y reserva.","imagen":"/assets/educacion/logistica-07-e.svg","sha256":"65de3e51f457b305168182d9ad75b09143f7589bdd0b37645f78589bfc403ca4"},{"numero":7,"posicion":6,"id":"logistica-07-f","titulo":"Construir y operar son cuentas distintas","texto":"La planificación distingue inversión inicial, como vías y trenes, de gastos de operación, como personal y materiales. En un ejercicio de Logística, se pueden comparar recursos de construcción y funcionamiento de dos diseños de metro, sin tratar la inversión inicial como si cubriera también la operación.","aprendizaje":"Diferenciar inversión inicial y gasto operativo","fuente":"MIT OpenCourseWare, Public Transportation Systems, Lecture 7: Cost Estimation (2017), p. 1 del PDF","url":"https://ocw.mit.edu/courses/1-258j-public-transportation-systems-spring-2017/354e8a5bb66fa39450b92d29066e8bf6_MIT1_258JS17_lec07.pdf","descripcion":"La construcción de una red y su operación cotidiana requieren tipos distintos de recursos.","imagen":"/assets/educacion/logistica-07-f.svg","sha256":"9303e331604d3000798aef64ced284ce2a3961d8f993e48879aa8ac5cf967f38"},{"numero":8,"posicion":1,"id":"8-1","titulo":"Frenar puede recuperar energía","texto":"Algunos trenes eléctricos utilizan frenado regenerativo: recuperan parte de la energía del movimiento y la devuelven al sistema eléctrico. En el metro de Londres, esa energía puede ayudar a mover otro tren. Su aprovechamiento depende de los equipos y de cómo funciona la red; no toda la energía se recupera.","aprendizaje":"La eficiencia también depende de cómo opera el sistema.","fuente":"TfL, informe anual 2015–2016","url":"https://content.tfl.gov.uk/tfl-annual-report-2015-16.pdf","descripcion":"Tren frenando, línea eléctrica y otro tren acelerando con flechas de energía.","imagen":"/assets/educacion/frenado-energia.svg","sha256":"6817eaa38f39333de0bf934f5d27ddd30373935eb122a2983144167ff8a887d0"},{"numero":8,"posicion":2,"id":"8-2","titulo":"La obra también deja una huella","texto":"Para comparar transportes no alcanza con mirar lo que emiten durante un viaje. El IPCC distingue también emisiones asociadas a fabricar vehículos y construir infraestructura. Una evaluación completa considera esas etapas junto con el funcionamiento del servicio. Tener motores eléctricos no convierte automáticamente una red en un sistema sin impacto.","aprendizaje":"Pensar en el ciclo de vida completo.","fuente":"IPCC, alcance de las emisiones del transporte","url":"https://www.ipcc.ch/report/ar6/wg3/figures/chapter-10/figure-10-1","descripcion":"Materiales, construcción, operación y mantenimiento en secuencia.","imagen":"/assets/educacion/ciclo-vida.svg","sha256":"939792a6d3177996db22ff8173deef00c1f3ea02b3276aec1d11f69ae1132374"},{"numero":8,"posicion":3,"id":"8-3","titulo":"Seis mil luces para ahorrar","texto":"En febrero de 2025, Londres anunció la instalación de 6.000 luces LED en la estación King’s Cross St Pancras. Estas lámparas consumen menos electricidad y duran más que la iluminación fluorescente anterior. Ahorrar energía en un metro también incluye sus estaciones, no solamente los motores de los trenes.","aprendizaje":"Buscar eficiencia en edificios e instalaciones de la red.","fuente":"TfL, comunicado de febrero de 2025","url":"https://tfl.gov.uk/info-for/media/press-releases/2025/february/6-000-lights-at-king-s-cross-st-pancras-converted-to-leds-providing-brighter-and-greener-journeys-for-passengers","descripcion":"Estación con luminarias LED y una anotación sobre 6.000 luces instaladas en 2025.","imagen":"/assets/educacion/led-estacion-2025.svg","sha256":"b2060ae4769f7c91b4c82ed04456dfe1021d2bcb2d3ba3c8ee5c55d5900c5a35"},{"numero":8,"posicion":4,"id":"8-4","titulo":"El calor del túnel puede servir","texto":"En Islington, Londres, el sistema Bunhill aprovecha aire caliente extraído de túneles de la línea Northern. Una bomba de calor utiliza ese calor para calentar agua que circula hacia edificios del barrio. Así, parte de la energía que sale del metro puede tener otro uso fuera de sus estaciones.","aprendizaje":"Reconocer oportunidades de aprovechar calor residual.","fuente":"Islington Council, Bunhill Heat and Power","url":"https://www.islington.gov.uk/environment-and-energy/energy/bunhill-heat-network","descripcion":"El aire caliente de un túnel llega a una bomba de calor que calienta agua distribuida a edificios cercanos.","imagen":"/assets/educacion/calor-tunel-bunhill.svg","sha256":"b169c7781dc9fb3a6bb8a4d6aeb908325a2ccc4abc75a2c18c848e696961badd"},{"numero":8,"posicion":5,"id":"logistica-08-e","titulo":"¿A qué lugares permite llegar?","texto":"El indicador británico de conectividad considera los destinos alcanzables y el tiempo necesario para llegar. Tener una estación cerca es solo parte del análisis. En Logística, podés revisar sobre un plano de metro si viviendas, centros de estudio y servicios quedan conectados, distinguiendo cobertura cercana de posibilidades de viaje por la red.","aprendizaje":"Distinguir proximidad a una estación y acceso a destinos","fuente":"Department for Transport, Transport connectivity metric, apartados The model y Factors affecting node values","url":"https://www.gov.uk/government/publications/transport-connectivity-metric/transport-connectivity-metric","descripcion":"Una estación cercana a una vivienda permite alcanzar algunos destinos, mientras otro queda aislado de la red.","imagen":"/assets/educacion/logistica-08-e.svg","sha256":"98e51fddc6f06d62fd528c2671d514ea76631ae3dec04dee9fe1cf97a64637f0"},{"numero":8,"posicion":6,"id":"logistica-08-f","titulo":"El beneficio no llega igual a todos","texto":"La evaluación de transporte del Reino Unido analiza cómo los beneficios y problemas afectan a distintos grupos sociales. Para estudiantes de Logística, una red de metro puede estudiarse barrio por barrio: compará qué zonas ganan destinos y cuáles siguen aisladas. Un buen resultado total puede ocultar diferencias importantes dentro del mismo mapa.","aprendizaje":"Revisar la distribución territorial de las mejoras","fuente":"Department for Transport, TAG A4.2 Distributional Impact Appraisal, presentación de la guía (actualización 2024)","url":"https://www.gov.uk/government/publications/tag-unit-a4-2-distributional-impact-appraisal","descripcion":"La misma ampliación de metro conecta nuevos destinos para un barrio, mientras otro sigue aislado.","imagen":"/assets/educacion/logistica-08-f.svg","sha256":"a970a2e0d9d6a9430e6a51e6c9c913780d9ee512c71680d38a12ebf54ec9b84b"},{"numero":9,"posicion":1,"id":"9-1","titulo":"El clima también afecta al metro","texto":"Las inundaciones, tormentas y olas de calor pueden interrumpir redes de transporte. Londres incluye estos riesgos en su planificación y contempla medidas como sistemas de refrigeración y jardines que gestionan el agua de lluvia. Diseñar una red duradera también exige pensar cómo seguirá funcionando cuando cambien las condiciones.","aprendizaje":"La confiabilidad incluye preparación ante riesgos.","fuente":"TfL, adaptación al cambio climático","url":"https://tfl.gov.uk/corporate/about-tfl/adapting-to-climate-change?intcmp=72525","descripcion":"Red bajo sol y lluvia con un escudo de protección y drenaje.","imagen":"/assets/educacion/clima-proteccion.svg","sha256":"fa346312a39c2d62e70a5bc14169c0a2962cbe7c18643a60fc92f134fc89ff74"},{"numero":9,"posicion":2,"id":"9-2","titulo":"El agua no viene solamente de la lluvia","texto":"En su revisión de riesgos de inundación, Transport for London identificó las roturas de cañerías como una amenaza importante para el Underground. La lección es sorprendente: una red subterránea comparte la ciudad con otras infraestructuras. Cuidar estaciones y túneles requiere conocer también lo que sucede alrededor.","aprendizaje":"Una red depende de otros servicios urbanos.","fuente":"TfL, revisión de riesgos y adaptación","url":"https://tfl.gov.uk/corporate/about-tfl/adapting-to-climate-change?intcmp=72525","descripcion":"Corte esquemático de calle, cañería con fuga y túnel separado.","imagen":"/assets/educacion/caneria-tunel.svg","sha256":"819510a8992b84241412251c91b249a20478f84fb3c36348d7385f51bd25b12b"},{"numero":9,"posicion":3,"id":"9-3","titulo":"Rieles blancos contra el calor","texto":"En un documento de adaptación climática, TfL incluye pintar rieles de blanco para reflejar calor. El acero se dilata con temperaturas altas y puede deformarse. Para un metro con tramos al aire libre, estudiar el calor ayuda a decidir dónde reforzar controles y cómo proteger la continuidad del servicio.","aprendizaje":"Estudiar riesgos térmicos de tramos en superficie.","fuente":"TfL, Climate Change and Planning for Unpredictable Weather Events","url":"https://content.tfl.gov.uk/sshrp-20170321-item09-climate-change-and-planning.pdf","descripcion":"Esquema de una medida de adaptación: parte lateral de un riel exterior pintada de blanco para reflejar calor.","imagen":"/assets/educacion/riel-blanco-calor.svg","sha256":"2b1a17359057f87dd860ae901f6d2f853784bcca1dcb8b4365e7db265b9027f0"},{"numero":9,"posicion":4,"id":"9-4","titulo":"Hojas pequeñas, demoras reales","texto":"Un informe de TfL de febrero de 2025 describe cómo la caída de hojas dañó ruedas en los tramos al aire libre de la línea Piccadilly. Hubo menos trenes disponibles y cierres parciales. Una alteración pequeña en la vía puede terminar afectando la frecuencia de todo un servicio.","aprendizaje":"Relacionar vía, disponibilidad de trenes y frecuencia.","fuente":"TfL, Commissioner’s report, febrero de 2025","url":"https://content.tfl.gov.uk/tfl-commissioners-report-february-2025-acc.pdf","descripcion":"Secuencia de hojas en la vía, ruedas dañadas y menos trenes disponibles para prestar servicio.","imagen":"/assets/educacion/hojas-piccadilly-2025.svg","sha256":"8b1ffdf30008a4b6dd160c86bd827403ff982246663568899222bda92dae2fb8"},{"numero":9,"posicion":5,"id":"logistica-09-e","titulo":"Una segunda ruta puede ayudar","texto":"La autoridad de transporte de Singapur relaciona las rutas alternativas con una red más resistente a interrupciones. En un ejercicio de Logística, tapá una estación en un dibujo de tu metro y buscá otro camino entre los extremos. Si no existe, identificaste una dependencia que merece atención al planificar conexiones.","aprendizaje":"Detectar dependencias y caminos alternativos","fuente":"Land Transport Authority, Upcoming Projects, introducción sobre conectividad, confiabilidad y rutas alternativas","url":"https://www.lta.gov.sg/content/ltagov/en/upcoming_projects.html","descripcion":"Una estación cerrada corta una ruta, pero una segunda conexión permite seguir uniendo sus extremos.","imagen":"/assets/educacion/logistica-09-e.svg","sha256":"16a6958f6d3eba201b0a9051cf6c5a3ace2cd333005e8efa72e7f34a4ce39754"},{"numero":9,"posicion":6,"id":"logistica-09-f","titulo":"Las obras también necesitan un plan","texto":"Para trabajos de marzo de 2026, Singapur anunció cambios de servicio entre Tanah Merah y Expo, acompañados por trenes lanzadera y ómnibus de conexión. La operación del metro debía reorganizarse mientras avanzaban las obras. En Logística, estudiar un cierre hipotético ayuda a distinguir el trazado permanente del servicio que puede ofrecerse temporalmente.","aprendizaje":"Planificar continuidad durante cierres de infraestructura","fuente":"Land Transport Authority, East–West Line Train Service Adjustments, folleto para el 14–17 de marzo de 2026","url":"https://www.lta.gov.sg/content/dam/ltagov/Interactive_map/pdf/EWL%20Train%20Service%20Adjustments%20Brochure%20-%2014%20to%2017%20Mar.pdf","descripcion":"Un tramo de metro en obras se sustituye temporalmente por un ómnibus mientras otro tramo mantiene un tren lanzadera.","imagen":"/assets/educacion/logistica-09-f.svg","sha256":"334868ec4af22cb7f3d8388e981105a36a7d62ce8809bfd691b252538e0c280b"},{"numero":10,"posicion":1,"id":"10-1","titulo":"Estudiar no significa inaugurar","texto":"En abril de 2025, el MTOP presentó un estudio sobre un posible servicio ferroviario de pasajeros para el área metropolitana, con atención al corredor de la ruta 5. Un estudio de factibilidad analiza si una propuesta puede funcionar. No significa que ese servicio ya esté construido o circulando.","aprendizaje":"Distinguir propuesta, estudio y servicio operativo.","fuente":"MTOP, estudio de factibilidad ferroviaria","url":"https://www.gub.uy/ministerio-transporte-obras-publicas/comunicacion/noticias/se-presento-estudio-factibilidad-para-implementar-servicio-ferroviario","descripcion":"Etapas separadas de estudio, obra y operación, con 2025 visible.","imagen":"/assets/educacion/estudio-ferroviario.svg","sha256":"dfc18e41d50ab32bef22b1e6f4b2bd0ca01005e905f1d4ec4e88be0d7f472051"},{"numero":10,"posicion":2,"id":"10-2","titulo":"Elegir el sistema adecuado","texto":"En marzo de 2026, el MTOP publicó una comparación de ómnibus de tránsito rápido, tren ligero y metro ligero para corredores metropolitanos. Analizaron capacidad, funcionamiento, inserción urbana y costos iniciales. Elegir transporte no consiste solamente en escoger un vehículo: implica encontrar una solución adecuada para cada corredor.","aprendizaje":"Comparar demanda, espacio, operación y costo.","fuente":"MTOP, análisis comparativo de alternativas modales","url":"https://www.gub.uy/ministerio-transporte-obras-publicas/comunicacion/noticias/analisis-comparativo-alternativas-modales-para-area-metropolitana-montevideo","descripcion":"Tres alternativas de transporte ante el mismo corredor, sin ganadora universal.","imagen":"/assets/educacion/alternativas-2026.svg","sha256":"00506685afcdcd480018a2b847b3b186cd61298201d3a5e533c4ecfd6ebbc799"},{"numero":10,"posicion":3,"id":"10-3","titulo":"La tarifa también conecta el metro","texto":"En Santiago, buses, Metro y Tren Nos comparten una tarifa integrada con reglas de tiempo y transbordo. Esto permite combinar modos dentro de un mismo viaje. Al pensar una futura red de metro para Uruguay, también conviene estudiar cómo se pagarían y conectarían sus viajes con otros servicios.","aprendizaje":"Evaluar conexiones considerando tiempo y costo del pasajero.","fuente":"Red Movilidad, Conoce las tarifas","url":"https://www.red.cl/tarifas-y-recargas/conoce-las-tarifas/","descripcion":"Esquema de red ficticia con conexiones de metro, reloj y tarjeta de viaje, sin precios.","imagen":"/assets/educacion/tarifa-integrada.svg","sha256":"652b254f6a3fbeb5bd27d931389dba52f070d0704e7321b2857b31517b7d7f1d"},{"numero":10,"posicion":4,"id":"10-4","titulo":"De los datos a la frecuencia","texto":"Montevideo combina datos de GPS de ómnibus y registros de pago para estimar viajes. Esa experiencia muestra el valor de estudiar la demanda antes de proponer una red. En una simulación de metro para Uruguay, los datos ayudan a comparar frecuencias, sin confundir una estimación con pasajeros futuros asegurados.","aprendizaje":"Transformar datos de demanda en hipótesis de servicio.","fuente":"Intendencia de Montevideo, Analítica de datos","url":"https://montevideo.gub.uy/areas-tematicas/servicios-digitales/desarrollo-sostenible-e-inteligente/analitica-de-datos","descripcion":"Datos de viajes alimentan una simulación que compara frecuencias y ocupación de estaciones de metro.","imagen":"/assets/educacion/datos-y-frecuencia.svg","sha256":"45b80087d13805a1c33fcdba37f733171c7825026826d2fa4b1adc00217875d3"},{"numero":10,"posicion":5,"id":"logistica-10-e","titulo":"Probá también otro supuesto","texto":"La guía británica de modelos de transporte pide documentar supuestos y comprobar cómo cambian los resultados al variar las condiciones. En Logística, podés comparar dos diseños de metro con el mismo objetivo de cobertura y registrar sus recursos. Después, cambiá una condición del ejercicio y explicá si tu elección sigue teniendo sentido.","aprendizaje":"Defender una decisión y comprobar su sensibilidad","fuente":"Department for Transport, TAG M1.1 Principles of Modelling and Forecasting (2024), §6.2 y cuadro 1","url":"https://assets.publishing.service.gov.uk/media/666af22a50dca4553304f333/tag-unit-m1.1-principles-modelling-forecasting.pdf","descripcion":"Dos diseños de metro se comparan con el mismo objetivo y vuelven a revisarse cuando cambia un supuesto.","imagen":"/assets/educacion/logistica-10-e.svg","sha256":"8a850dbfd1856f781b20a5e64de034a290f1552777d405f4a2cd566a8c250f9b"},{"numero":10,"posicion":6,"id":"logistica-10-f","titulo":"Una tesis miró el viaje completo","texto":"En 2009, David Uniman estudió la confiabilidad del Underground londinense usando datos de tarjetas de viaje. Su tesis de Transporte y Planificación Urbana analizó variaciones entre orígenes y destinos. Es un aporte universitario documentado: estudiantes de Logística pueden inspirarse en su pregunta central, cómo medir el servicio desde la experiencia de quien viaja.","aprendizaje":"Formular investigaciones centradas en la experiencia del pasajero","fuente":"MIT DSpace, David Louis Uniman, Service reliability measurement framework using smart card data: application to the London Underground (2009), resumen y titulación","url":"https://dspace.mit.edu/entities/publication/4d7ae0f7-3472-4458-9156-576bbfd918dc","descripcion":"Una investigación universitaria compara la variación de los viajes entre dos estaciones del metro.","imagen":"/assets/educacion/logistica-10-f.svg","sha256":"f6a7eb3ef252f5d569a0935b201cef69596c9b5220e1af302f5cb6cb0c1c9c15"}]
$metronet_tarjetas$::jsonb) AS t(numero INTEGER,posicion SMALLINT,id TEXT,titulo TEXT,texto TEXT,
  aprendizaje TEXT,fuente TEXT,url TEXT,descripcion TEXT,imagen TEXT,sha256 TEXT)
JOIN escenario e ON e.progresivo=TRUE AND e.modo='NIVEL' AND e.numero=t.numero
JOIN nivel_publicacion p ON p.id_escenario=e.id_escenario AND p.numero_version=1
ON CONFLICT(id_nivel_publicacion,posicion) DO NOTHING;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM nivel_publicacion p WHERE p.numero_version=1
    AND (SELECT COUNT(*) FROM nivel_publicacion_tarjeta t WHERE t.id_nivel_publicacion=p.id_nivel_publicacion) <> 6) THEN
    RAISE EXCEPTION '018 requiere seis tarjetas en cada publicación inicial';
  END IF;
END $$;

INSERT INTO nivel_borrador(id_escenario,version_base,contenido,red_referencia,tarjetas)
SELECT p.id_escenario,1,p.contenido,p.red_referencia,
  (SELECT jsonb_agg(jsonb_build_object('id',t.id_tarjeta,'titulo',t.titulo,'texto',t.texto,
    'aprendizaje',t.aprendizaje,'fuente',t.fuente,'urlFuente',t.url_fuente,
    'descripcionImagen',t.descripcion_imagen,'idSvgCatalogo',t.id_svg_catalogo)
    ORDER BY t.posicion) FROM nivel_publicacion_tarjeta t WHERE t.id_nivel_publicacion=p.id_nivel_publicacion)
FROM nivel_publicacion p WHERE p.numero_version=1
ON CONFLICT(id_escenario) DO NOTHING;

UPDATE intento i SET id_nivel_publicacion=p.id_nivel_publicacion
FROM nivel_publicacion p WHERE i.id_escenario=p.id_escenario AND p.numero_version=1
  AND i.id_nivel_publicacion IS NULL AND i.id_intento <= p.corte_id_intento;

REVOKE ALL ON TABLE nivel_borrador,nivel_publicacion,nivel_publicacion_tarjeta FROM PUBLIC;
REVOKE ALL ON SEQUENCE nivel_publicacion_id_nivel_publicacion_seq FROM PUBLIC;
GRANT SELECT,INSERT,UPDATE ON TABLE nivel_borrador TO metronet_app;
GRANT SELECT,INSERT ON TABLE nivel_publicacion,nivel_publicacion_tarjeta TO metronet_app;
GRANT USAGE ON SEQUENCE nivel_publicacion_id_nivel_publicacion_seq TO metronet_app;
GRANT UPDATE(id_nivel_publicacion) ON TABLE intento TO metronet_app;
COMMIT;
